mapper.select:
SELECT CAST(e.event_id AS VARCHAR) AS event_id, e.event_type, e.decision_st, e.event_at, l.location_nm AS location_name, a.patient_nm AS patient_name, h.emp_nm AS staff_name, a.crt_dt AS action_at, a.action_content, w.ward_nm AS ward_name FROM tb_detection_event e JOIN tb_location l ON l.location_id = e.location_id JOIN tb_ward w ON w.ward_id = l.ward_id LEFT JOIN tb_event_action a ON a.event_id = e.event_id LEFT JOIN tb_emp h ON h.emp_id = a.handler_id WHERE w.hosp_div_id = #{hospitalId} AND e.event_type = 'FALL' AND e.decision_st = 'CONFIRMED' AND (e.event_detail ->> 'duplicate_of') IS NULL
AND w.ward_id = #{wardId}
ORDER BY e.event_at DESC LIMIT #{limit}
